<?php declare(strict_types=1);

function b(){return json_decode(file_get_contents('php://input'),true)??[];}
function clientKey():string{return hash('sha256',$_SERVER['REMOTE_ADDR']??'unknown');}
function rateLimit(string $scope,string $key,int $limit,int $window):void{global $db;$bucket=(int)(time()/$window);$rateKey=$scope.':'.$key;$q=$db->prepare('INSERT INTO rate_limits(rate_key,window_start,request_count)VALUES(?,?,1) ON CONFLICT(rate_key) DO UPDATE SET window_start=excluded.window_start,request_count=CASE WHEN rate_limits.window_start=excluded.window_start THEN rate_limits.request_count+1 ELSE 1 END');$q->execute([$rateKey,$bucket]);$q=$db->prepare('SELECT request_count,window_start FROM rate_limits WHERE rate_key=?');$q->execute([$rateKey]);$row=$q->fetch(PDO::FETCH_ASSOC);if(!$row)return;if((int)$row['request_count']>$limit){$retry=max(1,((int)$row['window_start']+1)*$window-time());header('Retry-After: '.$retry);out(['error'=>'Too many requests'],429);}}
function validateLength(string $value,int $max,string $field):string{$value=trim($value);if($value===''||mb_strlen($value)>$max)out(['error'=>$field.' must contain between 1 and '.$max.' characters'],422);return $value;}function canViewPost(int $postId,int $userId):bool{global$db;$q=$db->prepare("SELECT p.user_id,COALESCE((SELECT private_account FROM user_settings s WHERE s.user_id=p.user_id),0) private_account FROM posts p WHERE p.id=?");$q->execute([$postId]);$post=$q->fetch(PDO::FETCH_ASSOC);if(!$post)return false;if(!(bool)$post['private_account']||((int)$post['user_id']===$userId))return true;$q=$db->prepare('SELECT 1 FROM follows WHERE follower_id=? AND following_id=?');$q->execute([$userId,(int)$post['user_id']]);return(bool)$q->fetchColumn();}function csrf(){if(in_array($_SERVER['REQUEST_METHOD'],['POST','PATCH','DELETE'],true)&&!hash_equals($_SESSION['csrf']??'',$_SERVER['HTTP_X_CSRF_TOKEN']??''))out(['error'=>'Invalid CSRF token'],419);}function out($x,$s=200){http_response_code($s);echo json_encode($x);exit;}function me(){global$db;if(empty($_SESSION['user_id']))out(['error'=>'Authentication required'],401);$q=$db->prepare('SELECT id,name,email,bio,avatar,created_at FROM users WHERE id=?');$q->execute([$_SESSION['user_id']]);return$q->fetch(PDO::FETCH_ASSOC);}function pu($id){global$db;$q=$db->prepare('SELECT id,name,email,bio,avatar FROM users WHERE id=?');$q->execute([$id]);return$q->fetch(PDO::FETCH_ASSOC);}